-- bf_activity  活动列表
CREATE TABLE IF NOT EXISTS "bf_activity" (
    "dbId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "actId" integer NOT NULL DEFAULT '0',
    "typeId" integer NOT NULL DEFAULT '0',
    "server_id" text,
    "name" varchar(255) DEFAULT '',
    "description" text NOT NULL,
    "timeType" integer NOT NULL DEFAULT '1',
    "startShowTime" varchar(64) NOT NULL DEFAULT '0',
    "endShowTime" varchar(64) NOT NULL DEFAULT '0',
    "startTime" varchar(64) NOT NULL DEFAULT '0',
    "endTime" varchar(64) NOT NULL DEFAULT '0',
    "status" smallint NOT NULL DEFAULT '0',
    "commonData" text,
    "editTime" bigint NOT NULL DEFAULT '0',
    "editUser" varchar(64) NOT NULL DEFAULT '',
    "isModify" smallint NOT NULL DEFAULT '0',
    "switchStatus" smallint NOT NULL DEFAULT '1',
    "failServer" text,
    "groupCount" integer NOT NULL DEFAULT '0',
    "confirmStatus" smallint NOT NULL DEFAULT '0',
    "oldStat" smallint NOT NULL DEFAULT '1',
    PRIMARY KEY ("dbId")
);
COMMENT ON TABLE "bf_activity" IS '活动列表';
COMMENT ON COLUMN "bf_activity"."actId" IS '活动Id';
COMMENT ON COLUMN "bf_activity"."typeId" IS '活动类型ID';
COMMENT ON COLUMN "bf_activity"."server_id" IS '区服ID';
COMMENT ON COLUMN "bf_activity"."name" IS '活动名称';
COMMENT ON COLUMN "bf_activity"."description" IS '活动描述';
COMMENT ON COLUMN "bf_activity"."timeType" IS '1-正常时间  2-开服时间';
COMMENT ON COLUMN "bf_activity"."startShowTime" IS '展示时间';
COMMENT ON COLUMN "bf_activity"."endShowTime" IS '展示结束时间';
COMMENT ON COLUMN "bf_activity"."startTime" IS '开始时间';
COMMENT ON COLUMN "bf_activity"."endTime" IS '结束时间';
COMMENT ON COLUMN "bf_activity"."status" IS '状态：0-待处理  1-待刷新到服务器  2-已刷新到服务器';
COMMENT ON COLUMN "bf_activity"."commonData" IS '公共参数（json格式）';
COMMENT ON COLUMN "bf_activity"."editTime" IS '编辑时间';
COMMENT ON COLUMN "bf_activity"."editUser" IS '编辑人员';
COMMENT ON COLUMN "bf_activity"."isModify" IS '0-为编辑  1-已编辑';
COMMENT ON COLUMN "bf_activity"."switchStatus" IS '开关 0-关闭 1-开启';
COMMENT ON COLUMN "bf_activity"."failServer" IS '推送失败的区服';
COMMENT ON COLUMN "bf_activity"."groupCount" IS '分组个数： 本服活动-0 跨服活动-必须大于等于2';
COMMENT ON COLUMN "bf_activity"."confirmStatus" IS '跨服分组确认状态：0-未确认 1-已确认';
COMMENT ON COLUMN "bf_activity"."oldStat" IS '是否旧活动 1-新活动 2-旧活动';
CREATE INDEX IF NOT EXISTS "bf_activity_name" ON "bf_activity" ("name");
CREATE INDEX IF NOT EXISTS "bf_activity_status" ON "bf_activity" ("status");
CREATE INDEX IF NOT EXISTS "bf_activity_actId_typeId" ON "bf_activity" ("actId", "typeId");
CREATE INDEX IF NOT EXISTS "bf_activity_startTime" ON "bf_activity" ("startTime");
CREATE INDEX IF NOT EXISTS "bf_activity_timeType" ON "bf_activity" ("timeType");
CREATE INDEX IF NOT EXISTS "bf_activity_endShowTime" ON "bf_activity" ("endShowTime");
