COMMENT ON COLUMN "bf_word_config"."qq_name" IS 'QQ客服名称';
COMMENT ON COLUMN "bf_word_config"."wechat" IS '微信号';
COMMENT ON COLUMN "bf_word_config"."qq" IS 'QQ号';

-- bf_world_cup  世界杯赔率配置
CREATE TABLE IF NOT EXISTS "bf_world_cup" (
    "dbId" integer GENERATED BY DEFAULT AS IDENTITY,
    "wid" integer DEFAULT '0',
    "stage" integer DEFAULT '0',
    "round" integer DEFAULT '0',
    "home_team" integer DEFAULT '0',
    "visiting_team" integer DEFAULT '0',
    "home_team_scored" integer DEFAULT '0',
    "visiting_team_scored" integer DEFAULT '0',
    "odds" real DEFAULT '0',
    "starttime" varchar(10) DEFAULT '0',
    "home" varchar(500) DEFAULT '',
    "draw" varchar(255) DEFAULT '',
    "away" varchar(500) DEFAULT '',
    "settlement" varchar(10) DEFAULT '',
    "endtime" varchar(10) DEFAULT '',
    PRIMARY KEY ("dbId")
);
COMMENT ON TABLE "bf_world_cup" IS '世界杯赔率配置';
COMMENT ON COLUMN "bf_world_cup"."wid" IS '赛事id';
COMMENT ON COLUMN "bf_world_cup"."stage" IS '赛事阶段';
COMMENT ON COLUMN "bf_world_cup"."round" IS '赛事轮次';
COMMENT ON COLUMN "bf_world_cup"."home_team" IS '主队国家id';
COMMENT ON COLUMN "bf_world_cup"."visiting_team" IS '客队国家id';
COMMENT ON COLUMN "bf_world_cup"."home_team_scored" IS '主队得分';
COMMENT ON COLUMN "bf_world_cup"."visiting_team_scored" IS '客队得分';
COMMENT ON COLUMN "bf_world_cup"."odds" IS '最后赔率';
COMMENT ON COLUMN "bf_world_cup"."starttime" IS '比赛开始时间';
COMMENT ON COLUMN "bf_world_cup"."home" IS '主队胜赔率';
COMMENT ON COLUMN "bf_world_cup"."draw" IS '平局赔率';
COMMENT ON COLUMN "bf_world_cup"."away" IS '客队胜赔率';
COMMENT ON COLUMN "bf_world_cup"."settlement" IS '结算赔率';
COMMENT ON COLUMN "bf_world_cup"."endtime" IS '竞猜结束时间:时间到了无法继续修改赔率参数';
CREATE UNIQUE INDEX IF NOT EXISTS "bf_world_cup_wid" ON "bf_world_cup" ("wid");

-- bf_world_cup_odds  世界杯赔率参数配置表
CREATE TABLE IF NOT EXISTS "bf_world_cup_odds" (
    "dbId" integer GENERATED BY DEFAULT AS IDENTITY,
    "wid" integer DEFAULT '0',
    "score" varchar(10) DEFAULT '',
    "odds" integer DEFAULT '0',
    "date" varchar(20) DEFAULT '',
    "type" smallint DEFAULT '0',
    PRIMARY KEY ("dbId")
);
COMMENT ON TABLE "bf_world_cup_odds" IS '世界杯赔率参数配置表';
COMMENT ON COLUMN "bf_world_cup_odds"."wid" IS '赛事ID';
COMMENT ON COLUMN "bf_world_cup_odds"."score" IS '比赛得分';
COMMENT ON COLUMN "bf_world_cup_odds"."odds" IS '赔率';
COMMENT ON COLUMN "bf_world_cup_odds"."date" IS '日期';
COMMENT ON COLUMN "bf_world_cup_odds"."type" IS '胜负类型：1：主队胜，2：平，3：客队胜';
CREATE UNIQUE INDEX IF NOT EXISTS "bf_world_cup_odds_wid_score" ON "bf_world_cup_odds" ("wid", "score");

-- bf_world_server  世界服（战斗匹配服）
CREATE TABLE IF NOT EXISTS "bf_world_server" (
    "dbId" bigint GENERATED BY DEFAULT AS IDENTITY,
    "type" integer NOT NULL DEFAULT '0',
    "channel_id" integer NOT NULL DEFAULT '0',
    "server_name" varchar(255) NOT NULL DEFAULT '',
    "remoteUrl" varchar(255) NOT NULL DEFAULT '',
    "api_url" varchar(45) NOT NULL,
    "status" smallint NOT NULL DEFAULT '0',
    PRIMARY KEY ("dbId")
);
COMMENT ON TABLE "bf_world_server" IS '世界服（战斗匹配服）';
COMMENT ON COLUMN "bf_world_server"."type" IS '服务器类型';
COMMENT ON COLUMN "bf_world_server"."channel_id" IS '渠道ID';
COMMENT ON COLUMN "bf_world_server"."remoteUrl" IS '远程接口访问地址';
COMMENT ON COLUMN "bf_world_server"."status" IS '0-未启动 1-已启动';
CREATE INDEX IF NOT EXISTS "bf_world_server_server_id" ON "bf_world_server" ("type", "channel_id");

-- cdk
CREATE TABLE IF NOT EXISTS "cdk" (
    "cdk" varchar(255) DEFAULT NULL
);
COMMENT ON COLUMN "cdk"."cdk" IS 'cdk';

-- cdk1
CREATE TABLE IF NOT EXISTS "cdk1" (
    "userid" varchar(255) NOT NULL,
    "code" varchar(255) DEFAULT NULL,
    PRIMARY KEY ("userid")
);

-- user
CREATE TABLE IF NOT EXISTS "user" (
    "username" varchar(255) NOT NULL,
    "password" varchar(255) NOT NULL,
    "reqTime" integer DEFAULT NULL,
    "money" integer DEFAULT '0',
    "dayTime" integer DEFAULT '0',
    PRIMARY KEY ("username")
);
COMMENT ON COLUMN "user"."username" IS '账号';
COMMENT ON COLUMN "user"."password" IS '密码';
COMMENT ON COLUMN "user"."reqTime" IS '注册时间';
COMMENT ON COLUMN "user"."money" IS '平台币';
COMMENT ON COLUMN "user"."dayTime" IS '每天领取时间';

-- user_cdk
CREATE TABLE IF NOT EXISTS "user_cdk" (
    "cdk" varchar(255) DEFAULT NULL,
    "userid" varchar(255) NOT NULL,
    PRIMARY KEY ("userid")
);
